test("primitive-base native PHP CI counts the Composer ZIP once", () => {
	const archive = "handoff/archives/example-nominalprimitivesubtypes-1.0.0-linux-x86_64.zip";
	const records = ["report.json", archive, "package/src/Api.php"];
	assert.deepEqual(nominalPrimitiveSubtypePhpCiArtifactPaths(records, archive)
		, [...records].sort());
	assert.throws(() => nominalPrimitiveSubtypePhpCiArtifactPaths(
		["report.json", "package/src/Api.php"], archive));
	assert.throws(() => nominalPrimitiveSubtypePhpCiArtifactPaths(
		[...records, archive], archive));
	assert.throws(() => nominalPrimitiveSubtypePhpCiArtifactPaths(
		[...records, "report.json"], archive));
});

 * Require the retained record list to contain the Composer ZIP exactly once.
 *
 * @param records - Complete selection-relative paths returned by the report checker.
 * @param archivePath - Independently authenticated Composer ZIP path.
 */
export const nominalPrimitiveSubtypePhpCiArtifactPaths = (records, archivePath) => {
	assert.ok(Array.isArray(records));
	assert.equal(typeof archivePath, "string");
	assert.equal(records.filter(path => path === archivePath).length, 1);
	assert.equal(new Set(records).size, records.length);
	return [...records].sort();
};

